                </div>
                {error && <div role="alert" className="mt-5 flex items-start gap-3 rounded-xl bg-urgent-soft p-4 text-sm font-semibold text-urgent"><CircleAlert className="mt-0.5 size-5 shrink-0" />{error}</div>}
