@import "tailwindcss" source(none);
@source "../src";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Design system definition.
 *
 * The @theme inline block maps CSS custom properties to Tailwind utility
 * classes (e.g. --color-primary -> bg-primary, text-primary).
 *
 * The :root and .dark blocks define the actual color values using oklch.
 * All colors MUST use oklch format.
 *
 * Palette direction: calm, trustworthy healthcare.
 * Deep navy/charcoal text, warm off-white canvas, emerald/teal primary,
 * subtle amber for attention, and red reserved for urgent states only.
 */

@theme inline {
  --font-sans: "Manrope", sans-serif;
  --font-display: "Sora", sans-serif;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 12px);
  --radius-4xl: calc(var(--radius) + 16px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-ring-offset-background: var(--background);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-routine: var(--routine);
  --color-routine-soft: var(--routine-soft);
  --color-attention: var(--attention);
  --color-attention-soft: var(--attention-soft);
  --color-urgent: var(--urgent);
  --color-urgent-soft: var(--urgent-soft);
  --color-low: var(--low);
  --color-low-soft: var(--low-soft);
  --color-hero: var(--hero);
  --shadow-soft: 0 14px 35px color-mix(in oklab, var(--foreground) 9%, transparent);
  --shadow-card: 0 1px 2px color-mix(in oklab, var(--foreground) 4%, transparent),
    0 24px 48px -24px color-mix(in oklab, var(--foreground) 20%, transparent);
  --shadow-lifted: 0 18px 40px -18px color-mix(in oklab, var(--foreground) 24%, transparent);
}

:root {
  --radius: 0.75rem;
  --background: oklch(0.975 0.01 92);
  --foreground: oklch(0.235 0.03 240);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.235 0.03 240);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.235 0.03 240);
  --primary: oklch(0.52 0.1 176);
  --primary-foreground: oklch(0.99 0.004 170);
  --secondary: oklch(0.948 0.022 168);
  --secondary-foreground: oklch(0.33 0.06 176);
  --muted: oklch(0.956 0.01 92);
  --muted-foreground: oklch(0.49 0.032 226);
  --accent: oklch(0.88 0.082 84);
  --accent-foreground: oklch(0.32 0.06 66);
  --destructive: oklch(0.55 0.2 28);
  --destructive-foreground: oklch(0.985 0.004 30);
  --border: oklch(0.905 0.016 100);
  --input: oklch(0.905 0.016 100);
  --ring: oklch(0.6 0.1 176);
  --routine: oklch(0.52 0.115 155);
  --routine-soft: oklch(0.945 0.04 152);
  --attention: oklch(0.62 0.13 68);
  --attention-soft: oklch(0.955 0.045 84);
  --urgent: oklch(0.55 0.2 28);
  --urgent-soft: oklch(0.952 0.035 27);
  --low: oklch(0.56 0.13 248);
  --low-soft: oklch(0.948 0.03 247);
  --hero: oklch(0.205 0.035 240);
  --chart-1: oklch(0.52 0.1 176);
  --chart-2: oklch(0.66 0.13 68);
  --chart-3: oklch(0.56 0.13 248);
  --chart-4: oklch(0.57 0.2 28);
  --chart-5: oklch(0.55 0.12 155);
  --sidebar: oklch(0.984 0.003 247.858);
  --sidebar-foreground: oklch(0.235 0.03 240);
  --sidebar-primary: oklch(0.208 0.042 265.755);
  --sidebar-primary-foreground: oklch(0.984 0.003 247.858);
  --sidebar-accent: oklch(0.968 0.007 247.896);
  --sidebar-accent-foreground: oklch(0.208 0.042 265.755);
  --sidebar-border: oklch(0.929 0.013 255.508);
  --sidebar-ring: oklch(0.704 0.04 256.788);
}

.dark {
  --background: oklch(0.16 0.03 240);
  --foreground: oklch(0.96 0.012 240);
  --card: oklch(0.2 0.035 240);
  --card-foreground: oklch(0.96 0.012 240);
  --popover: oklch(0.2 0.035 240);
  --popover-foreground: oklch(0.96 0.012 240);
  --primary: oklch(0.7 0.12 176);
  --primary-foreground: oklch(0.16 0.04 240);
  --secondary: oklch(0.27 0.04 240);
  --secondary-foreground: oklch(0.96 0.012 240);
  --muted: oklch(0.27 0.04 240);
  --muted-foreground: oklch(0.7 0.03 240);
  --accent: oklch(0.85 0.09 84);
  --accent-foreground: oklch(0.2 0.05 60);
  --destructive: oklch(0.68 0.2 27);
  --destructive-foreground: oklch(0.98 0.004 30);
  --border: oklch(1 0 0 / 12%);
  --input: oklch(1 0 0 / 16%);
  --ring: oklch(0.7 0.12 176);
  --routine: oklch(0.7 0.13 155);
  --routine-soft: oklch(0.28 0.06 152);
  --attention: oklch(0.82 0.13 84);
  --attention-soft: oklch(0.3 0.07 84);
  --urgent: oklch(0.72 0.21 27);
  --urgent-soft: oklch(0.32 0.08 27);
  --low: oklch(0.75 0.13 248);
  --low-soft: oklch(0.3 0.07 248);
  --hero: oklch(0.13 0.03 240);
  --chart-1: oklch(0.7 0.12 176);
  --chart-2: oklch(0.82 0.13 84);
  --chart-3: oklch(0.75 0.13 248);
  --chart-4: oklch(0.72 0.21 27);
  --chart-5: oklch(0.7 0.13 155);
  --sidebar: oklch(0.18 0.03 240);
  --sidebar-foreground: oklch(0.96 0.012 240);
  --sidebar-primary: oklch(0.7 0.12 176);
  --sidebar-primary-foreground: oklch(0.16 0.04 240);
  --sidebar-accent: oklch(0.27 0.04 240);
  --sidebar-accent-foreground: oklch(0.96 0.012 240);
  --sidebar-border: oklch(1 0 0 / 12%);
  --sidebar-ring: oklch(0.7 0.12 176);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    letter-spacing: -0.011em;
    min-width: 320px;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  button,
  input,
  select,
  textarea {
    font: inherit;
  }

  a:focus-visible,
  summary:focus-visible,
  input:focus-visible,
  select:focus-visible,
  textarea:focus-visible {
    outline: 2px solid var(--color-ring);
    outline-offset: 2px;
    border-radius: 6px;
  }

  ::selection {
    background: var(--secondary);
    color: var(--foreground);
  }

  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }
}

@keyframes scan {
  0% { transform: translateY(-12px); opacity: 0; }
  15%, 85% { opacity: 1; }
  100% { transform: translateY(210px); opacity: 0; }
}

@keyframes rise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fade-up {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes float-slow {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

@keyframes typing-dot {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-4px); opacity: 1; }
}

@utility animate-rise { animation: rise 0.45s ease-out both; }
@utility animate-scan { animation: scan 2.6s ease-in-out infinite; }
@utility animate-fade-up { animation: fade-up 0.6s cubic-bezier(0.22, 1, 0.36, 1) both; }
@utility animate-fade-in { animation: fade-in 0.5s ease-out both; }
@utility animate-float-slow { animation: float-slow 7s ease-in-out infinite; }
@utility animate-typing-dot { animation: typing-dot 1.2s ease-in-out infinite; }

@utility text-gradient {
  background-image: linear-gradient(100deg, var(--color-primary), oklch(0.64 0.13 178));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

import { useEffect, useRef, useState, type ReactNode } from "react";

import { cn } from "@/lib/utils";

/** Fade/slide content in when it scrolls into view. Respects prefers-reduced-motion. */
export function Reveal({
  children,
  className,
  delay = 0,
}: {
  children: ReactNode;
  className?: string;
  delay?: number;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setShown(true);
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setShown(true);
          observer.disconnect();
        }
      },
      { threshold: 0.12, rootMargin: "0px 0px -48px 0px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      className={cn(
        "transition-all duration-700 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform",
        shown ? "translate-y-0 opacity-100" : "translate-y-5 opacity-0",
        className,
      )}
      style={{ transitionDelay: delay ? `${delay}ms` : undefined }}
    >
      {children}
    </div>
  );
}

import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

type Props = {
  eyebrow?: string;
  title: ReactNode;
  subtitle?: string;
  align?: "center" | "left";
  className?: string;
  titleClassName?: string;
};

export function SectionHeading({
  eyebrow,
  title,
  subtitle,
  align = "center",
  className,
  titleClassName,
}: Props) {
  return (
    <div
      className={cn(
        "max-w-2xl",
        align === "center" && "mx-auto text-center",
        className,
      )}
    >
      {eyebrow && (
        <p
          className={cn(
            "flex items-center gap-2 text-xs font-bold uppercase tracking-[0.18em] text-primary",
          )}
        >
          <span className="size-1.5 rounded-full bg-primary" />
          {eyebrow}
        </p>
      )}
      <h2
        className={cn(
          "mt-4 font-display text-3xl font-semibold tracking-tight leading-[1.15] sm:text-4xl",
          titleClassName,
        )}
      >
        {title}
      </h2>
      {subtitle && (
        <p className="mx-auto mt-4 max-w-xl text-base leading-7 text-muted-foreground">
          {subtitle}
        </p>
      )}
    </div>
  );
}

import { CircleAlert, ShieldAlert, Sparkles } from "lucide-react";

import { cn } from "@/lib/utils";

export type Flag = "normal" | "high" | "low" | "unknown";
export type Urgency = "Routine" | "Needs Attention" | "Urgent";

const flagTone: Record<Flag, { pill: string; dot: string; label: string }> = {
  normal: { pill: "bg-routine-soft text-routine", dot: "bg-routine", label: "Normal" },
  high: { pill: "bg-attention-soft text-attention", dot: "bg-attention", label: "High" },
  low: { pill: "bg-low-soft text-low", dot: "bg-low", label: "Low" },
  unknown: { pill: "bg-muted text-muted-foreground", dot: "bg-muted-foreground", label: "Unknown" },
};

const urgencyTone: Record<Urgency, { classes: string; dot: string; icon: typeof CircleAlert }> = {
  Routine: { classes: "bg-routine-soft text-routine", dot: "bg-routine", icon: Sparkles },
  "Needs Attention": { classes: "bg-attention-soft text-attention", dot: "bg-attention", icon: CircleAlert },
  Urgent: { classes: "bg-urgent-soft text-urgent", dot: "bg-urgent", icon: ShieldAlert },
};

export function FlagDot({ flag, className }: { flag: Flag; className?: string }) {
  return <span aria-hidden className={cn("size-2.5 shrink-0 rounded-full", flagTone[flag].dot, className)} />;
}

export function FlagPill({ flag, label }: { flag: Flag; label?: string }) {
  return (
    <span className={cn("inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold uppercase tracking-wide", flagTone[flag].pill)}>
      <span className={cn("size-1.5 rounded-full", flagTone[flag].dot)} />
      {label ?? flagTone[flag].label}
    </span>
  );
}

export function UrgencyBadge({
  urgency,
  className,
  size = "md",
}: {
  urgency: Urgency;
  className?: string;
  size?: "sm" | "md";
}) {
  const tone = urgencyTone[urgency];
  const Icon = tone.icon;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 rounded-full font-bold",
        size === "sm" ? "px-3 py-1 text-xs" : "px-3.5 py-1.5 text-sm",
        tone.classes,
        className,
      )}
    >
      <span className={cn("size-1.5 rounded-full", tone.dot)} aria-hidden />
      <Icon className="size-3.5" aria-hidden />
      {urgency}
    </span>
  );
}

import { FileImage, UploadCloud, X } from "lucide-react";
import { useEffect, useRef, useState, type DragEvent } from "react";

import { cn } from "@/lib/utils";

type UploadDropzoneProps = {
  file: File | null;
  preview: string;
  error: string;
  onFile: (file: File) => void;
  onRemove: () => void;
  scanning?: boolean;
  className?: string;
  accept?: string;
};

export function UploadDropzone({
  file,
  preview,
  error,
  onFile,
  onRemove,
  scanning = false,
  className,
  accept = "image/jpeg,image/png,image/webp",
}: UploadDropzoneProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [dragging, setDragging] = useState(false);

  useEffect(() => {
    if (!preview) return;
    return () => URL.revokeObjectURL(preview);
  }, [preview]);

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(false);
    const next = event.dataTransfer.files?.[0];
    if (next instanceof File) onFile(next);
  };

  return (
    <div className={cn("space-y-4", className)}>
      <div
        role="button"
        tabIndex={0}
        aria-label={file ? "Preview of your lab report. Press Enter to replace it." : "Upload your lab report. Drag and drop or press Enter to browse."}
        onClick={() => inputRef.current?.click()}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            inputRef.current?.click();
          }
        }}
        onDragOver={(event) => {
          event.preventDefault();
          setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={handleDrop}
        className={cn(
          "relative min-h-[320px] cursor-pointer overflow-hidden rounded-3xl border-2 border-dashed outline-none transition-all duration-300",
          dragging
            ? "scale-[1.005] border-primary bg-primary/5"
            : file
              ? "border-primary/30 bg-secondary/25"
              : "border-input bg-muted/40 hover:border-primary/55 hover:bg-muted/60",
          className,
        )}
      >
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          aria-hidden
          tabIndex={-1}
          className="pointer-events-none absolute inset-0 size-full opacity-0"
          onChange={(event) => {
            const next = event.target.files?.[0];
            if (next) onFile(next);
            event.target.value = "";
          }}
        />

        {file && preview ? (
          <>
            <img
              src={preview}
              alt="Selected lab report preview"
              className="absolute inset-0 size-full object-contain p-6"
            />
            {scanning && (
              <div className="pointer-events-none absolute inset-x-8 top-0 h-px bg-primary shadow-[0_0_18px_var(--primary)] animate-scan" />
            )}
            <button
              type="button"
              aria-label="Remove selected image"
              onClick={(event) => {
                event.stopPropagation();
                onRemove();
              }}
              className="absolute right-4 top-4 z-10 grid size-9 place-items-center rounded-full border border-border bg-background/90 text-foreground shadow-soft transition-all hover:scale-105 hover:border-urgent/40 hover:text-urgent"
            >
              <X className="size-4" />
            </button>
            <div className="absolute inset-x-0 bottom-0 flex items-center gap-3 bg-hero/85 px-6 py-4 text-primary-foreground backdrop-blur">
              <FileImage className="size-5 shrink-0 text-accent" />
              <div className="min-w-0">
                <p className="truncate text-sm font-bold">{file.name}</p>
                <p className="text-xs text-primary-foreground/70">
                  {(file.size / 1024 / 1024).toFixed(1)} MB · Ready to analyze
                </p>
              </div>
            </div>
          </>
        ) : (
          <div className="absolute inset-0 grid place-items-center px-6 text-center">
            <div>
              <span className="mx-auto grid size-16 place-items-center rounded-2xl bg-gradient-to-br from-primary to-[oklch(0.62_0.12_178)] text-primary-foreground shadow-soft">
                <UploadCloud className="size-7" />
              </span>
              <p className="mt-5 font-display text-xl font-semibold tracking-tight">
                Drop your lab report here
              </p>
              <p className="mt-1.5 text-sm text-muted-foreground">
                or click to browse · JPEG, PNG or WEBP
              </p>
              <div className="mt-5 inline-flex flex-wrap items-center justify-center gap-2">
                {["Up to 12 MB", "Private & secure", "English + Urdu"]}
                  .map((chip) => (
                    <span
                      key={chip}
                      className="rounded-full border border-border bg-background px-3 py-1 text-xs font-semibold text-muted-foreground"
                    >
                      {chip}
                    </span>
                  ))}
              </div>
            </div>
          </div>
        )}
      </div>

      {error && (
        <div
          role="alert"
          className="flex items-start gap-3 rounded-2xl border border-urgent/20 bg-urgent-soft px-4 py-3.5 text-sm font-semibold text-urgent animate-fade-in"
        >
          <span className="grid size-6 shrink-0 place-items-center rounded-full bg-urgent text-urgent-foreground">
            <span className="text-xs">!</span>
          </span>
          {error}
        </div>
      )}
    </div>
  );
}

