input.content:
import { createFileRoute, Link } from "@tanstack/react-router";
import {
  ArrowRight,
  Bot,
  Brain,
  CalendarCheck,
  CalendarDays,
  Check,
  CheckCircle2,
  ChevronDown,
  CircleAlert,
  Clock3,
  FileCheck2,
  Gauge,
  Languages,
  MapPin,
  MessageCircle,
  Phone,
  RotateCcw,
  ScanLine,
  ShieldAlert,
  ShieldCheck,
  Sparkles,
  Stethoscope,
  UploadCloud,
  UserRound,
} from "lucide-react";
import { useCallback, useEffect, useState, type FormEvent } from "react";

import heroImage from "@/assets/sehat-clinic-hero.jpg";
import { UrgencyBadge, FlagDot, FlagPill, type Flag, type Urgency } from "@/components/badges";
import { Reveal } from "@/components/reveal";
import { SectionHeading } from "@/components/section-heading";
import { SiteFooter, SiteHeader } from "@/components/site-chrome";
import { UploadDropzone } from "@/components/upload-dropzone";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

type ReportResult = {
  extraction: { values: Array<{ test_name: string; value: string; unit: string; reference_range: string; flag: Flag }>; raw_notes: string | null };
  interpretation: { items: Array<{ test_name: string; explanation_en: string; explanation_ur: string; next_step: string }>; disclaimer: string };
  urgency: { urgency: Urgency; reasoning: string };
  scheduling: { chosen_slot: { doctor_name: string; specialty: string; date: string; time: string; hospital_type: "government" | "private" }; reason: string };
};

// Keep the browser on the same origin by default. The hard-coded localhost:8000
// fallback made the deployed app send uploads to a server that does not exist
// in the browser's environment, which surfaced as a generic failure.
const API_BASE = import.meta.env["VITE_API_BASE_URL"] || "";
const acceptedTypes = ["image/jpeg", "image/png", "image/webp"];
const steps = ["Reading report", "Preparing explanation", "Checking urgency", "Finding appointment"];

export const Route = createFileRoute("/")({
  head: () => ({ meta: [
    { title: "Sehat Sahulat | Understand Your Lab Report" },
    { name: "description", content: "Upload a lab report for clear English and Urdu guidance, urgency checks, and a suggested appointment." },
    { property: "og:title", content: "Sehat Sahulat | Clear Lab Report Guidance" },
    { property: "og:description", content: "Understand your lab report in simple English and Urdu." },
    { property: "og:type", content: "website" },
    { name: "twitter:card", content: "summary_large_image" },
  ] }),
  component: Index,
});

const pipeline = [
  { icon: ScanLine, title: "Reads your report", body: "Every test name, value, unit and reference range is pulled from the photo and flagged normal, high or low." },
  { icon: Brain, title: "Explains it simply", body: "Each result is rewritten in everyday English and Urdu, with a practical next step for you." },
  { icon: Gauge, title: "Rates the urgency", body: "Routine, Needs Attention or Urgent — with the reasoning behind the rating in one short line." },
  { icon: CalendarCheck, title: "Suggests care", body: "A realistic appointment with the right specialist, at a government or private hospital." },
];

const benefits = [
  { icon: ScanLine, title: "Understand every value", body: "Your numbers translated into plain language — no jargon, and no unnecessary panic." },
  { icon: Languages, title: "Bilingual, always", body: "Every explanation is written in simple English and Urdu at the same time." },
  { icon: Gauge, title: "Know how urgent", body: "A clear Routine, Needs Attention or Urgent rating, with the reasoning explained." },
  { icon: MessageCircle, title: "A mentor on call", body: "Follow-up questions answered any time by the AI health mentor." },
];

function Index() {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState("");
  const [status, setStatus] = useState<"idle" | "loading" | "results">("idle");
  const [step, setStep] = useState(0);
  const [result, setResult] = useState<ReportResult | null>(null);
  const [error, setError] = useState("");

  useEffect(() => () => { if (preview) URL.revokeObjectURL(preview); }, [preview]);
  useEffect(() => {
    if (status !== "loading") return;
    const timer = window.setInterval(() => setStep((current) => Math.min(current + 1, steps.length - 1)), 3200);
    return () => window.clearInterval(timer);
  }, [status]);

  const chooseFile = useCallback((next: File) => {
    setError("");
    if (!acceptedTypes.includes(next.type)) { setError("Please upload a JPEG, PNG, or WEBP image"); return; }
    if (next.size > 12 * 1024 * 1024) { setError("Please choose an image smaller than 12 MB"); return; }
    if (preview) URL.revokeObjectURL(preview);
    setFile(next); setPreview(URL.createObjectURL(next)); setResult(null); setStatus("idle");
  }, [preview]);

  const removeFile = useCallback(() => {
    setFile(null); setPreview(""); setError("");
  }, []);

  const analyze = async () => {
    if (!file) return;
    setError(""); setStatus("loading"); setStep(0);
    const data = new FormData(); data.append("file", file);
    try {
      const response = await fetch(`${API_BASE}/api/process`, { method: "POST", body: data });
      if (!response.ok) {
        if (response.status === 400) throw new Error("Please upload a JPEG, PNG, or WEBP image");
        if (response.status === 422) throw new Error("Could not read this report clearly. Please try a clearer photo.");
        throw new Error("Something went wrong processing your report. Please try again.");
      }
      setResult(await response.json() as ReportResult); setStatus("results");
      window.setTimeout(() => document.querySelector("#results")?.scrollIntoView({ behavior: "smooth" }), 60);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Something went wrong processing your report. Please try again.");
      setStatus("idle");
    }
  };

  return (
    <main className="min-h-screen overflow-hidden bg-background">
      <SiteHeader floating />

      <Hero />

      <TrustStrip />

      <HowItWorks />

      <WhySection />

      <section id="upload" className="scroll-mt-20 border-t border-border bg-gradient-to-b from-background to-card/60 py-20 sm:py-28">
        <div className="mx-auto max-w-5xl px-5">
